-- GENERATED by `wfj generate` from data/gossip/gossip-e1.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["e1031d1d170e51ff"] = { "Quei due non mi sono mai piaciuti. Muoviamoci.", "." },
  ["e10b4d251b9eaf29"] = { "Immagino che potrebbe funzionare, se avessimo venti persone per lanciarlo insieme.", "." },
  ["e10fb6cd7d310824"] = { "Assaggia il cinghiale! È la mia nuova ricetta!", "." },
  ["e10fc9d20b0aac79"] = { "Salve, amici miei. È bello rivedervi. Vedo che continuate a tenere sgombri i nostri confini. Antonio apprezza il vostro duro lavoro.", "." },
  ["e114ab5b0be6d463"] = { "Vieni con me se vuoi vivere.", "." },
  ["e11c67e3f6f5ca3c"] = { "Un tempo capitale dei nani ⟦Dark Iron=Ferroscuro⟧, questo labirinto vulcanico è ora la sede del potere di Ragnaros, il Signore del Fuoco. Ragnaros ha scoperto il segreto per creare la vita dalla pietra e intende costruire un esercito di golem inarrestabili che lo aiutino a conquistare l'intero ⟦Blackrock Mountain=Massiccio Roccianera⟧. Ossessionato dalla sconfitta di Nefarian e dei suoi servitori draconici, Ragnaros è pronto a tutto pur di ottenere la vittoria finale.", "." },
  ["e1226fc93a8544b2"] = { "Tu non sei mica <un/una> <guerriero/guerriera>... Ma va', non dureresti neanche un giorno col mio addestramento!\n\n<Un/Una> {class} che si crede <un/una> <guerriero/guerriera>. Ah!", "." },
  ["e124ab2030461ac4"] = { "5 secondi alla detonazione!!!!!", "." },
  ["e12aed69731ec573"] = { "La Shattered Hand è riuscita a piazzare spie in tutta la cittadella superiore di ⟦Blackrock=Roccianera⟧. Anche se la raccolta di informazioni è stata lenta, abbiamo fatto scoperte che non si possono ignorare.", "." },
  ["e12d08ca2f2715fa"] = { "C'è un mago alla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧ che potrebbe insegnarti qualche nuovo incantesimo. Credo si chiami Magis Sparkmantle.", "." },
  ["e1325f3f8d8691fa"] = { "Che bello rivederti, Amy. Stai attenta, tesoro. Io vado a ⟦Goldshire=Borgodoro⟧.", "." },
  ["e13298704e2ee118"] = { "Che succede qui? Lascia stare quella polvere!", "." },
  ["e13592e8b74d6327"] = { "Affrontami, codardo. Affronta la fede e la forza che un tempo incarnavi.", "." },
  ["e136c2a2215b3480"] = { "Un grande male si risveglia, {race}. Lo senti?\n\nBah! Certo che no. Dammi la tua armatura e le tue armi e ridarò loro vigore.", "." },
  ["e13717d4ad2237fc"] = { "Che bello vedere un'altra persona in questa remota regione del mondo. Vieni, cammina con me. Lascia che i nostri corpi si scaldino a vicenda.", "." },
  ["e14050e5b2828e94"] = { "Davvero una bella pesca! Porti onore all'⟦Horde=Orda⟧, <ragazzo/ragazza>, ti ringraziamo!", "." },
  ["e1502aa67f40559f"] = { "Quali piante del ⟦Felwood=Vilbosco⟧ potrebbero essere corrotte?", "." },
  ["e15255b0502c90cb"] = { "Ti do il benvenuto nella ⟦Tower of Azora=Torre di Azora⟧, giovane {class}. Sono Theocritus.\n\nHai affari con me? O forse... sono io ad avere affari con te?", "." },
  ["e153a46ff8f2f2e3"] = { "Chi sei, debole {race}? Feccia che si intrufola, dico io. Muori, idiota!", "." },
  ["e15de035e23516f8"] = { "Oh, che bello, qualcos'altro da fare mentre aspetto! Mi salvi la vita, {name}!", "." },
  ["e15ebb11b476df4a"] = { "T'ho visto combattere meglio di così, Lana! La prossima volta li stendi! Tark, vai là dentro e fagli vedere i sorci verdi!", "." },
  ["e16174e4289959c3"] = { "Tanto erano solo d'intralcio.", "." },
  ["e165e44c6ddfd73c"] = { "Chi è il prevedibile, bestia? Credevi davvero che ti avremmo evocato sopra Malfurion? La tua redenzione è vicina, Eranikus. Sarai purificato da questa follia, da questa corruzione.", "." },
  ["e167d47690d18e3e"] = { "Non evocarmi più a meno che tu non abbia una vera domanda da farmi, d'accordo?", "." },
  ["e16802170d51b483"] = { "Mentre attraversavamo le ⟦Burning Steppes=Steppe Ardenti⟧, siamo caduti in un'imboscata. Dovevano essere un centinaio... Nani ⟦Dark Iron=Ferroscuro⟧! Uscivano dalle pareti, dalle rocce delle Steppe; da ogni crepa, angolo e anfratto in vista. Ci sono piombati addosso, sopraffacendo le guardie e i pochi coraggiosi eroi che avevano accettato di assisterci in questa missione.\n\nUna cosa era chiara: era un'imboscata organizzata con estrema cura. Era come se conoscessero ogni nostra mossa prima che la facessimo...", "." },
  ["e17f26a539a95572"] = { "E tu hai...", "." },
  ["e17f3edad66ff22d"] = { "La guerra continuò, ma la volontà del grande condottiero era fiaccata. Ben presto tutta ⟦Silithus=Silitus⟧ fu sommersa dai silitidi e dalle loro schiere qiraji.", "." },
  ["e18bcaccfb5876c6"] = { "Aiuto! Ti prego, devi aiutarmi!", "." },
  ["e1935fe7bd2fc212"] = { "Per questo vivrai per sempre nel tormento, <patetico/patetica> <stregone/strega>.", "." },
  ["e197ef677dfef050"] = { "Salve, {name}. Il mio nome è Chronormu, ma puoi chiamarmi Chromie. Tanta familiarità non mi dispiace.\n\nE ora... come faccio a sapere il tuo nome, chiedi? Appartengo allo Stormo dei Draghi di Bronzo, sempre in sintonia con il flusso e il riflusso del tempo. Si potrebbe dire che ci siamo già incontrati. Allo stesso modo, ci incontreremo di nuovo.\n\nSpero che l'aspetto che ho scelto non ti turbi; anche se il mio compito è vegliare su luoghi di dolore, scelgo di non annegare nella tristezza di questi posti.", "." },
  ["e1a32b9d1c1a220b"] = { "Cerco di tenere piene le scorte di ⟦Sentinel Hill=Guardiacolle⟧, e non è facile con tutti gli scontri che ci sono qui.", "." },
  ["e1af311db6524b64"] = { "Perché non provi a cercare al Lion's Pride Inn? Il cuoco potrebbe insegnarti qualche buona ricetta.", "." },
  ["e1b8528d15db4181"] = { "C'è ancora luce, quindi vediamo quella tua ascia spaccare ancora un po' di legna.", "." },
  ["e1c28885ef692074"] = { "Patchwerk vuole giocare!", "." },
  ["e1c2fc8c037d2b8f"] = { "Il tuo cuore batte al ritmo dei venti?", "." },
  ["e1c4d9917ce234c6"] = { "Chi è questo Lar'korwi di cui parlavi?", "." },
  ["e1d514e8b8e95b37"] = { "Mostra i ninnoli, Maltrake.", "." },
  ["e1d9992599875760"] = { "Ora abbiamo ciò che ci serve. Accenderemo la fiamma eterna e comunicheremo con gli spiriti del fuoco.", "." },
  ["e1ea0c1299ba0fe6"] = { "Ti prego, continua.", "." },
  ["e1ea23b43ec4302f"] = { "Se lo trovi, è tuo! Non dire a nessuno che Rin'ji ti ha parlato!", "." },
  ["e1ea353cdfe10488"] = { "Il nemico è alle porte, tenetevi pronti!", "." },
  ["e1f2707afa37cdda"] = { "Sei <il/la> <benvenuto/benvenuta> a Shen'dar Village, dove si pesca tra il meglio da questo lato della catena montuosa. Se vuoi imparare a pescare posso insegnarti io, a pagamento.", "." },
  ["e1f87c5e53fff943"] = { "Kildrath tende a drammatizzare la situazione. Per esempio, «⟦Garona: A Study on Stealth and Treachery=Garona: Studio sulla Furtività e sul Tradimento⟧» è stato rubato più di 400 volte.\n\nIl marchio dell'Athenaeum protegge i tomi, impedendo qualunque consultazione non autorizzata.", "." },
  ["e1fb6d9eab2be0b0"] = { "Spendere monete NON è il senso della Festa del Grande Inverno!", "." },
})
